class Gradebook:
    def __init__(self) -> None:
        # Maps assignment name -> dict with 'weight' and 'kind'
        self.assignments: dict[str, dict] = {}
        # Maps student name -> dict of assignment_name -> grade
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale of 2.0 to 5.0.")

        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})
        if not student_grades:
            return 0.0

        # Separate recorded grades into quizzes and non-quizzes
        quiz_items: list[tuple[str, float, float]] = []  # (name, grade, weight)
        other_items: list[tuple[str, float, float]] = []

        for assignment_name, grade in student_grades.items():
            if assignment_name not in self.assignments:
                continue
            meta = self.assignments[assignment_name]
            weight = meta["weight"]
            kind = meta["kind"]

            if kind == "quiz":
                quiz_items.append((assignment_name, grade, weight))
            else:
                other_items.append((assignment_name, grade, weight))

        # If a student has more than one quiz, drop the lowest quiz grade.
        if len(quiz_items) > 1:
            # Sort by grade ascending; drop the first element (the lowest grade)
            quiz_items.sort(key=lambda item: item[1])
            quiz_items.pop(0)

        included_items = other_items + quiz_items
        total_weight = sum(weight for _, _, weight in included_items)

        if total_weight == 0.0:
            return 0.0

        weighted_sum = sum(grade * weight for _, grade, weight in included_items)
        return round(weighted_sum / total_weight, 2)
```

